CREATE COLUMN TABLE "TEST_AP"."OFCT" ("AbsID" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(16) NOT NULL , "Name" NVARCHAR(100), "UserSign" SMALLINT CS_INT, "StartDate" LONGDATE CS_LONGDATE, "EndDate" LONGDATE CS_LONGDATE, "FormView" NVARCHAR(1) DEFAULT 'D', PRIMARY KEY ("AbsID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OFCT_FCT_CODE" ON "TEST_AP"."OFCT" ( "Code" ASC )